// ──────────────────────────── tests ──────────────────────────────────────

List<Employee> Staff() =>
[
    new(1, "ada", "eng"),
    new(2, "bob", "sales"),
    new(3, "cleo", "eng"),
];

Test("groups and sorts both levels", () =>
    Eq(ByDepartment(Staff()), new[] { "eng: ada, cleo", "sales: bob" }));

Test("an empty staff list groups to nothing", () =>
    Eq(ByDepartment([]), new List<string>()));

Test("a lookup returns every name for a key", () =>
    Eq(NamesByDepartment(Staff())["eng"].OrderBy(n => n), new[] { "ada", "cleo" }));

Test("a lookup returns EMPTY for a missing key — it does not throw", () =>
{
    // The reason to prefer a lookup over a Dictionary<K, List<V>>.
    Eq(NamesByDepartment(Staff())["nope"].Count(), 0);
});

Test("a lookup knows whether it contains a key", () =>
{
    var lookup = NamesByDepartment(Staff());
    Ok(lookup.Contains("eng"));
    Ok(!lookup.Contains("nope"));
});

Test("ById maps every employee", () =>
{
    var byId = ById(Staff());
    Eq(byId.Count, 3);
    Eq(byId[2].Name, "bob");
});

Test("ToDictionary THROWS on a duplicate key", () =>
{
    // The trap. On data you do not control, this is a crash in waiting.
    var dupes = new List<Employee> { new(1, "ada", "eng"), new(1, "bob", "sales") };

    Throws<ArgumentException>(() => ById(dupes));
});

Test("headcount per department", () =>
    Eq(Headcount(Staff()), new[] { "eng=2", "sales=1" }));

Test("headcount of an empty list is empty", () =>
    Eq(Headcount([]), new List<string>()));

// ──────────────────────────── tests ──────────────────────────────────────

var players = new List<Player>
{
    new("Zoe", 50), new("Ada", 90), new("Bob", 50), new("Cy", 90),
};

Test("ranking is by score descending", () =>
    Eq(Ranked(players).Select(p => p.Score), new[] { 90, 90, 50, 50 }));

Test("ties are broken by name", () =>
    Eq(Ranked(players).Select(p => p.Name), new[] { "Ada", "Cy", "Bob", "Zoe" }));

Test("without a tiebreak, equal elements keep their INPUT order", () =>
{
    // OrderByDescending reverses the comparison, not the sequence. Zoe was
    // before Bob going in, so she is before Bob coming out.
    Eq(ByScoreOnly(players).Select(p => p.Name), new[] { "Ada", "Cy", "Zoe", "Bob" });
});

Test("the comparer orders by length first", () =>
{
    var words = new List<string> { "pear", "fig", "apple", "kiwi" };
    words.Sort(ByLengthThenText());

    Eq(words, new[] { "fig", "kiwi", "pear", "apple" });
});

Test("the same comparer works with OrderBy", () =>
    Eq(new[] { "bb", "a", "cc" }.OrderBy(w => w, ByLengthThenText()),
       new[] { "a", "bb", "cc" }));

Test("equal lengths fall back to ordinal order", () =>
    Eq(new[] { "cat", "ant", "bee" }.OrderBy(w => w, ByLengthThenText()),
       new[] { "ant", "bee", "cat" }));

Test("case-insensitive counting merges the spellings", () =>
{
    var counts = CountIgnoringCase("Ada", "ada", "ADA", "bob");

    Eq(counts.Count, 2);
    Eq(counts["ada"], 3);
    Eq(counts["ADA"], 3);
});

Test("the stored key is the FIRST spelling seen", () =>
{
    // The comparer decides which keys are equal. It does not rewrite a key
    // that is already there — so the capitalisation you get back is
    // whichever one arrived first.
    var counts = CountIgnoringCase("Ada", "ada", "ADA");

    Eq(counts.Keys.Single(), "Ada");
});

// ──────────────────────────── tests ──────────────────────────────────────

static List<Item> Sample() =>
[
    new("a", false), new("b", true), new("c", true), new("d", false),
];

Test("DropExpired removes them in place", () =>
{
    var items = Sample();
    DropExpired(items);

    Eq(items.Select(i => i.Name), new[] { "a", "d" });
});

Test("WithoutExpired leaves the original alone", () =>
{
    var items = Sample();
    var kept = WithoutExpired(items);

    Eq(kept.Select(i => i.Name), new[] { "a", "d" });
    Eq(items.Count, 4);
});

Test("the backwards loop gets the same answer", () =>
{
    var items = Sample();
    DropExpiredBackwards(items);

    Eq(items.Select(i => i.Name), new[] { "a", "d" });
});

Test("ADJACENT removals are where the forwards loop breaks", () =>
{
    // "b" and "c" are next to each other. Remove "b" at index 1, "c" slides
    // into index 1, the loop moves to index 2, and "c" is never examined.
    var items = Sample();
    ForwardsAndBroken(items);

    Eq(items.Select(i => i.Name), new[] { "a", "c", "d" });
    Ok(items.Any(i => i.Expired), "the broken loop is supposed to miss one");
});

Test("...and it does it silently", () =>
{
    // No exception. That is the whole problem: the crash you get from
    // foreach is a gift by comparison.
    var items = Sample();
    ForwardsAndBroken(items);

    Ok(items.Count == 3);
});

Test("foreach + Remove throws instead", () =>
{
    var items = Sample();
    Throws<InvalidOperationException>(() => ForeachAndThrows(items));
});

Test("DropZeroes clears the empty counts", () =>
{
    var counts = new Dictionary<string, int> { ["a"] = 1, ["b"] = 0, ["c"] = 2, ["d"] = 0 };
    DropZeroes(counts);

    Eq(counts.Keys.OrderBy(k => k), new[] { "a", "c" });
});

Test("DropZeroes on an all-zero dictionary empties it", () =>
{
    var counts = new Dictionary<string, int> { ["a"] = 0, ["b"] = 0 };
    DropZeroes(counts);

    Eq(counts.Count, 0);
});

