// The bug, preserved so the tests can point at it.
static void ForwardsAndBroken(List<Item> items)
{
    for (var i = 0; i < items.Count; i++)
        if (items[i].Expired)
            items.RemoveAt(i);
}

static void ForeachAndThrows(List<Item> items)
