{
    var graph = new Dictionary<string, string[]>
    {
        ["a"] = ["b"],
        ["b"] = ["a"],      // a cycle: without a visited set this loops forever
        ["z"] = [],
    };

    Eq(Hops(graph, "a", "z"), -1);
