    var graph = new Dictionary<string, string[]>
    {
        ["a"] = ["b", "c"],
        ["b"] = ["d"],
        ["c"] = ["d"],
        ["d"] = ["e"],
        ["e"] = [],
    };

    Eq(Hops(graph, "a", "e"), 3);
    Eq(Hops(graph, "a", "d"), 2);
    Eq(Hops(graph, "a", "a"), 0);
